import unittest

class Contract(unittest.TestCase):
    def test_contract(self):
        import archivepath as m
        for value in ('file', 'dir/file', './a', 'a..b'): self.assertTrue(m.safe(value))
        for value in ('', '/x', '../x', 'a/../x', 'a\\b'): self.assertFalse(m.safe(value))
